import{_ as o,o as d,c,a3 as a}from"./chunks/framework.BZCmpA0A.js";const h=JSON.parse('{"title":"Spec 06：WUWAOS 簡易檔案系統與磁碟 I/O","description":"","frontmatter":{},"headers":[],"relativePath":"SPEC-06-filesystem.md","filePath":"SPEC-06-filesystem.md","lastUpdated":1792953178000}'),l={name:"SPEC-06-filesystem.md"};function i(s,e,n,r,t,p){return d(),c("div",null,[...e[0]||(e[0]=[a(`<h1 id="spec-06-wuwaos-簡易檔案系統與磁碟-i-o" tabindex="-1">Spec 06：WUWAOS 簡易檔案系統與磁碟 I/O <a class="header-anchor" href="#spec-06-wuwaos-簡易檔案系統與磁碟-i-o" aria-label="Permalink to &quot;Spec 06：WUWAOS 簡易檔案系統與磁碟 I/O&quot;">​</a></h1><h2 id="目標" tabindex="-1">目標 <a class="header-anchor" href="#目標" aria-label="Permalink to &quot;目標&quot;">​</a></h2><p>在 QEMU 上接入可持久保存的虛擬磁碟，並建立 WUWAOS 自有的簡易檔案系統。Linux 風格的 <code>/bin</code>、<code>/boot</code>、<code>/dev</code>、<code>/home/user</code> 只代表目錄命名慣例，不要求 Linux 格式相容。</p><h2 id="範圍" tabindex="-1">範圍 <a class="header-anchor" href="#範圍" aria-label="Permalink to &quot;範圍&quot;">​</a></h2><ul><li>實作 QEMU <code>virt</code> 平台上的 VirtIO-MMIO 區塊裝置讀寫，從 OpenSBI 傳入的 FDT（硬體裝置樹）尋找裝置，不硬編碼裝置位址。</li><li>實作固定 512-byte 區塊的 WUFS 格式：superblock、inode bitmap、block bitmap、固定 inode 表、直接與單層索引區塊指標、目錄項目。檔案上限約 516 KiB；使用小型、固定上限，先不做動態掛載、多磁碟、權限位元、連結、日誌或快取。</li><li>建立根目錄與 <code>/bin</code>、<code>/boot</code>、<code>/dev</code>、<code>/home</code>、<code>/home/user</code>。首次初始化空白磁碟時建立；辨識到既有 WUFS 後保留使用者資料。</li><li>提供路徑查找、列目錄、建立目錄／檔案、讀取與覆寫一般檔案。shell 至少可用 <code>ls</code>、<code>mkdir</code>、<code>touch</code>、<code>cat</code>、<code>write</code> 操作絕對路徑。第一版採專用 path-based（以路徑為參數）系統呼叫，尚未實作 POSIX 檔案描述號與 <code>open/close</code>。</li><li>把目前建置的 <code>kernel.elf</code> 作為一般檔案 <code>/boot/kernel.elf</code> 放入虛擬磁碟。此階段依然由 QEMU <code>-kernel</code> 載入正在執行的核心；磁碟中的核心副本不負責開機。</li><li>block I/O 採單核心同步輪詢；尚無 block cache、DMA IOMMU、多核心鎖或磁碟中斷處理。</li><li>不新增測試程式碼。使用一般 shell 命令操作，並在重新啟動 QEMU 後確認文字檔保留。</li></ul><h2 id="分層" tabindex="-1">分層 <a class="header-anchor" href="#分層" aria-label="Permalink to &quot;分層&quot;">​</a></h2><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>user shell command</span></span>
<span class="line"><span>  → user syscall wrapper</span></span>
<span class="line"><span>  → kernel syscall / VFS-style path interface</span></span>
<span class="line"><span>  → WUFS inode and directory operations</span></span>
<span class="line"><span>  → block read/write API</span></span>
<span class="line"><span>  → VirtIO-MMIO block driver</span></span>
<span class="line"><span>  → QEMU raw disk image</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>UART console 與 pipe 保持為其他 I/O 端點，不經過 WUFS。檔案操作、終端操作、pipe 各自使用明確系統呼叫／介面；目前 <code>kernel/io.c</code> 管理 console 與 pipe，<code>kernel/block.c</code> 提供的 VirtIO 區塊 I/O 則只供磁碟檔案系統使用。兩者都屬於核心的輸入輸出功能，但尚未整合成通用裝置或檔案描述號架構。</p><h2 id="驗收條件" tabindex="-1">驗收條件 <a class="header-anchor" href="#驗收條件" aria-label="Permalink to &quot;驗收條件&quot;">​</a></h2><ul><li>核心可識別 QEMU VirtIO block device，讀寫區塊成功；裝置未出現或回報錯誤時輸出診斷並繼續以 shell 啟動，檔案功能回報不可用。</li><li>第一次使用新磁碟建立目錄樹與 <code>/boot/kernel.elf</code>；再次啟動時保留磁碟內容而不重格式化。</li><li><code>ls /</code> 可見預設目錄；可建立 <code>/home/user/note.txt</code>、寫入、讀回內容，關閉 QEMU 後重開仍讀到相同內容。</li><li>建置工具更新 <code>/boot/kernel.elf</code> 時保留其他 inode 與檔案內容；QEMU 實際執行中的核心仍由 <code>-kernel</code> 載入。</li><li>既有 QEMU 開機、shell、行程生命週期與固定 pipe 行為不回歸。</li><li>文件說明 WUFS 格式限制、IO 路徑及 kernel file 與目前直接開機方式的差異。</li></ul><h2 id="實作與驗收紀錄" tabindex="-1">實作與驗收紀錄 <a class="header-anchor" href="#實作與驗收紀錄" aria-label="Permalink to &quot;實作與驗收紀錄&quot;">​</a></h2><h3 id="_2026-10-26-inode-跨磁區修復" tabindex="-1">2026-10-26：inode 跨磁區修復 <a class="header-anchor" href="#_2026-10-26-inode-跨磁區修復" aria-label="Permalink to &quot;2026-10-26：inode 跨磁區修復&quot;">​</a></h3><ul><li>目標與範圍：修復 <code>inode_read</code>／<code>inode_write</code> 對 80-byte inode 的單磁區緩衝區越界存取；保留 WUFS0001 格式、inode 編號、既有磁碟與檔案內容，不變更主記憶體管理架構。</li><li>設計：由 <code>number * 80 + copied</code> 計算目前磁區與區內位移，每次只複製 <code>min(512 - offset, 80 - copied)</code> bytes，再處理下一段。寫入採逐磁區 read-modify-write（先讀、局部修改、再寫回），保留同磁區其他 inode。移除 sector buffer 直接轉型成 <code>Inode *</code> 的存取。</li><li>步驟與驗收：先編譯，再使用既有磁碟工具建立獨立的 <code>build/inode-check.img</code>，在 QEMU 以一般 shell 指令操作跨界 inode 及相鄰 inode，關閉後重開確認內容保留。未新增測試程式碼，未使用或修改原有 <code>build/wuwaos.img</code>。</li><li>結果：<code>make</code> 通過 <code>-Wall -Wextra -Werror</code>。新卷的 inode 6（<code>/boot/kernel.elf</code>，磁區內位移 480，分為 32 + 48 bytes）可讀取並覆寫成 <code>inode-six</code>；此操作只在獨立驗證磁碟執行。inode 12（<code>/home/user/d12</code>，位移 448，分為 64 + 16 bytes）可建立目錄、建立並讀寫 <code>nested</code> 子檔。相鄰 inode 11／13 的 <code>a11</code>／<code>a13</code> 分別讀回 <code>before-boundary</code>／<code>after-boundary</code>。QEMU 重啟後四個路徑內容及目錄項目均保留，子檔再次覆寫讀回成功；固定 <code>writer | reader</code> 完成 80 bytes、EOF 與子行程回收。</li><li>限制：跨兩個磁區的寫入不是交易；第二段 I/O 失敗或中途掉電時，仍可能留下部分更新。此修復不提供日誌、不修復舊程式可能已造成的磁碟損壞；未注入裝置錯誤或驗證所有 128 個 inode。</li></ul><p>2026-10-19：Clang 18／QEMU 8.2.2／OpenSBI 1.3，單核心 <code>virt</code>。核心由 OpenSBI 傳入 FDT（硬體裝置樹）尋找 VirtIO-MMIO block，確認 VERSION_1 後設定單一同步輪詢佇列；QEMU 使用 <code>-global virtio-mmio.force-legacy=false</code>。核心映射發現的裝置頁面後，WUFS 才讀寫磁碟。</p><ul><li><code>make run</code> 建立或更新 16 MiB raw disk；更新 <code>/boot/kernel.elf</code> 時原有 WUFS 會保留其他檔案。WUFS 共 128 inode，固定目錄項目每個名稱 24 bytes，支援 8 個直接區塊與 8 個單層索引表，每檔最多 1032 個 512-byte 區塊。</li><li>QEMU 顯示 <code>VirtIO block ready, sectors=32768</code>、<code>Mounted existing WUFS volume</code>。<code>ls /</code> 列出 bin、boot、dev、home，<code>ls /boot</code> 列出 kernel.elf。</li><li>建立 <code>/home/user/notes.txt</code>，寫入 <code>WUWAOS-filesystem</code>，退出 QEMU 後再次 <code>make run</code>，讀回相同 17 bytes；再建立 <code>/home/user/notes/today.txt</code>，寫入並讀回 <code>filesystem-works</code>。重複建立既有 notes 目錄回 -17。</li><li><code>make</code> 通過 <code>-Wall -Wextra -Werror</code>；實際 QEMU 操作不是測試程式碼，未新增測試檔。</li></ul><p>限制：第一版 shell 的 <code>write</code> 只接受一個不含空白的文字 token，<code>cat</code> 顯示上限 2048 bytes；若顯示內容非空且未以 LF（換行字元）結尾，shell 會在輸出後補一個換行，不改動檔案內容。syscall 每次最多處理單一使用者資料頁，因此目前互動寫入最多 4 KiB。沒有刪除／改名／追加、相對路徑、cwd、檔案描述號、開機載入、掉電交易保護或壞磁碟復原。block I/O 同步輪詢，失效裝置可能讓核心等待；目前沒有 block cache。</p>`,16)])])}const u=o(l,[["render",i]]);export{h as __pageData,u as default};
